// Core Talk as ONE stage under the v3 look (owner, 25 Nov), in a real Chromium on the built app (dist-e2e) against the sandbox.
// The core routes and the event socket are mocked here, so the four states are driven the way the engine drives them: the
// GET /api/core answer, the `state` events and the voice frames (`level`, `out_level`) on /ws/events. Every frame below is
// GENERATED by this test (a formula, not a recording); the screen is only asked to draw what it is sent.
//
//   VITE_ART_TRACK=private npx vite build --outDir dist-e2e
//   WW_SANDBOX_PORT=8881 WW_PREVIEW_PORT=5281 WW_SANDBOX_DIR="$TEMP/jarvis-ui-talk-e2e" npx playwright test e2e/core-talk-stage.spec.ts
//
// Proves: at 1366 x 768 and 390 x 844 the orb is large (at least 180 px) and centred, the bar, the stage, the words, the act
// row and the conversation do not overlap, the newest turn is fully visible and fully opaque at the bottom of the log, every
// key is 44 px, no page error; pressing the orb POSTs /api/core/start with the chosen mode and the screen shows the answer;
// a measured frame changes the level words to dB and LIVE, and a frame gone stale brings "no level" back; reduced motion
// leaves no running animation in the view. Screenshots of each state go to SHOTS ($TEMP/ui-talk-shots by default).
import { mkdirSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { resolve } from 'node:path'
import type { Page, WebSocketRoute } from '@playwright/test'
import { expect, test } from './fixtures'

const SHOTS = resolve(process.env.UI_TALK_SHOTS ?? resolve(process.env.TEMP ?? tmpdir(), 'ui-talk-shots'))
const shot = (name: string) => { mkdirSync(SHOTS, { recursive: true }); return resolve(SHOTS, `${name}.png`) }
const DESKTOP = { width: 1366, height: 768 }
const PHONE = { width: 390, height: 844 }

const OFF = { running: false, mode: null, state: 'offline', boot_step: null, pid: null, started_at: null, ready_at: null, uptime_s: null, last_error: null, exit_code: null, timings: {}, room: {}, mqtt: null, status_line: 'Offline' }
const now = () => Date.now() / 1000
const awake = (state: string, extra: Record<string, unknown> = {}) => ({
  ...OFF, running: true, mode: 'voice', state, pid: 4242, started_at: now() - 300, ready_at: now() - 280, uptime_s: 300, status_line: 'Voice on the GPU, wake word on', mqtt: true, ...extra,
})
// invented lines, no one's real words
const T0 = 1_763_000_000
const TURNS = [
  ['you', 'What is on the list for chemistry?'], ['jarvis', 'Two short problem sets on equilibrium, then the lab write-up.'],
  ['you', 'How long is the write-up?'], ['jarvis', 'About forty minutes if you start with the graphs.'],
  ['you', 'Set a reminder for seven.'], ['jarvis', 'Done. Seven in the evening, the lab write-up.'],
  ['you', 'And turn the desk lamp on.'], ['jarvis', 'The desk lamp is on. The board confirmed it a moment ago, and the room reads warm and quiet.'],
].map(([role, text], i) => ({ id: i + 1, role, text, t: T0 + i * 20, done: true, ...(role === 'jarvis' ? { seconds: 1.6 + i * 0.1 } : {}), session: 'e2e' }))

/** A speech-shaped spectrum from a formula (24 bands, 0..255); `k` moves the formant so the frames differ. */
const bands = (k: number) => Array.from({ length: 24 }, (_, i) => Math.round(Math.max(0, Math.min(255, 40 + 180 * Math.exp(-((i - 6 - (k % 5) * 0.5) ** 2) / 20) + 60 * Math.exp(-((i - 15) ** 2) / 9)))))

interface Mock { core: Record<string, unknown>; turns: unknown[]; started: unknown[]; sockets: WebSocketRoute[] }

async function mockEngine(page: Page, m: Mock) {
  await page.route(/\/api\/core$/, (r) => r.fulfill({ json: m.core }))
  await page.route(/\/api\/core\/transcript$/, (r) => r.fulfill({ json: m.turns }))
  await page.route(/\/api\/core\/start$/, (r) => {
    m.started.push(r.request().postDataJSON())
    m.core = awake('booting', { boot_step: 'loading the speech model', uptime_s: 1 })
    return r.fulfill({ json: m.core })
  })
  await page.route(/\/api\/core\/stop$/, (r) => { m.core = OFF; return r.fulfill({ json: m.core }) })
  // the event socket is the test's: nothing reaches the sandbox, so the only events are the ones sent below
  await page.routeWebSocket(/\/ws\/events/, (ws) => { m.sockets.push(ws) })
}
const send = (m: Mock, ev: Record<string, unknown>) => { for (const ws of m.sockets) ws.send(JSON.stringify({ id: 0, ts: now(), source: 'core', text: '', ...ev })) }
async function frames(page: Page, m: Mock, kind: 'level' | 'out_level', n: number) {
  for (let i = 0; i < n; i++) {
    send(m, { kind, t: now(), seq: i, sr: 16000, rms_db: -24 + (i % 4), bands: bands(i) })
    await page.waitForTimeout(45)
  }
}

async function open(page: Page, baseURL: string | undefined, size: { width: number; height: number }) {
  const res = await fetch(baseURL!).catch(() => null)
  test.skip(!res || !res.ok, 'dist-e2e is not built, so the preview server is not running; run `npx vite build --outDir dist-e2e` first')
  await page.setViewportSize(size)
  await page.goto('/#t=ww-e2e&shell=v2&look=v3')
  await expect(page.locator('[data-shell="v2"]')).toBeVisible({ timeout: 15_000 })
  await page.evaluate(() => { location.hash = '#core/talk' })
  await expect(page.locator('.jc3 .jc3-hero')).toBeVisible({ timeout: 15_000 })
}

interface Box { x: number; y: number; width: number; height: number }
const overlap = (a: Box, b: Box) => Math.min(a.x + a.width, b.x + b.width) - Math.max(a.x, b.x) > 1 && Math.min(a.y + a.height, b.y + b.height) - Math.max(a.y, b.y) > 1
async function boxOf(page: Page, sel: string): Promise<Box> {
  const b = await page.locator(sel).first().boundingBox()
  expect(b, `${sel} has a box`).not.toBeNull()
  return b!
}

/** The parts of the stage do not overlap one another (the waves are drawn inside the stage and are not a part), and the
 *  two corners with the small keys never touch the orb or the words. */
async function expectNoOverlap(page: Page) {
  const parts = ['.jc3-stage', '.jc3-say', '.jc3-act', '.jc3-log']
  const boxes = await Promise.all(parts.map((s) => boxOf(page, s)))
  for (let i = 0; i < parts.length; i++) for (let j = i + 1; j < parts.length; j++) expect(overlap(boxes[i], boxes[j]), `${parts[i]} overlaps ${parts[j]}`).toBe(false)
  const orb = await boxOf(page, '.jc3-orb')
  const say = await boxOf(page, '.jc3-say')
  for (const side of ['left', 'right']) {
    const c = await boxOf(page, `.jc3-corner[data-side="${side}"]`)
    expect(overlap(c, orb), `the ${side} corner overlaps the orb`).toBe(false)
    expect(overlap(c, say), `the ${side} corner overlaps the words`).toBe(false)
  }
}

/** Every visible key of the view is at least 44 x 44 px. */
async function expectKeys44(page: Page) {
  const small = await page.evaluate(() => [...document.querySelectorAll<HTMLElement>('.jc3 .s3-tray[data-step="1"] button, .jc3 .s3-tray[data-step="1"] [role="radio"]')]
    .filter((b) => b.offsetParent !== null)
    .map((b) => ({ t: (b.getAttribute('aria-label') ?? b.textContent ?? '').slice(0, 30), w: b.getBoundingClientRect().width, h: b.getBoundingClientRect().height }))
    .filter((k) => k.w < 43.5 || k.h < 43.5))
  expect(small).toEqual([])
}

/** The newest turn: inside the log's viewport and in its fully opaque lower part (the mask is opaque below 40 percent). */
async function expectNewestClear(page: Page) {
  const r = await page.evaluate(() => {
    const sc = document.querySelector('.jc3-log-scroll')!.getBoundingClientRect()
    const rows = document.querySelectorAll('.jc3-log .jc3-turn')
    const last = rows[rows.length - 1].getBoundingClientRect()
    return { top: last.top, bottom: last.bottom, scTop: sc.top, scBottom: sc.bottom, opaqueFrom: sc.top + sc.height * 0.4 }
  })
  expect(r.bottom).toBeLessThanOrEqual(r.scBottom + 0.5)
  expect(r.top).toBeGreaterThanOrEqual(r.opaqueFrom - 0.5)
}

test.describe('Core Talk, one stage (v3 look)', () => {
  test('1366 x 768: asleep, the orb wakes, listening with a measured level, thinking, speaking', async ({ page, baseURL }) => {
    const errors: string[] = []
    page.on('pageerror', (e) => errors.push(e.message))
    const m: Mock = { core: OFF, turns: TURNS.slice(0, 2), started: [], sockets: [] }
    await mockEngine(page, m)
    await open(page, baseURL, DESKTOP)
    await page.waitForTimeout(700) // the trays have risen

    // asleep
    await expect(page.getByTestId('orb-word')).toHaveText('Asleep')
    const orb = await boxOf(page, '.jc3-orb')
    expect(orb.width).toBeGreaterThanOrEqual(180)
    const tray = await boxOf(page, '.s3-tray[data-step="1"]')
    expect(Math.abs(orb.x + orb.width / 2 - (tray.x + tray.width / 2))).toBeLessThan(4) // centred in its tray
    await expectNoOverlap(page)
    await expectKeys44(page)
    expect(await page.locator('.jc3 .jc-wake').count()).toBe(1)
    await page.screenshot({ path: shot('1366-asleep') })

    // the orb is the wake key: it POSTs the chosen mode and the screen shows the engine's answer
    await page.locator('button.jc3-orb').click()
    await expect.poll(() => m.started.length).toBe(1)
    expect(m.started[0]).toEqual({ mode: 'voice' })
    await expect(page.getByTestId('orb-word')).toHaveText('Waking')
    await expect(page.getByTestId('orb-line')).toHaveText('Starting: loading the speech model')
    await page.screenshot({ path: shot('1366-waking') })

    // ready, then listening with real (test-generated) mic frames
    m.core = awake('listening')
    m.turns = TURNS
    send(m, { kind: 'ready', text: 'JARVIS is ready' })
    await expect(page.getByTestId('orb-word')).toHaveText('Listening')
    await expect(page.getByTestId('orb-level')).toContainText('MIC no level yet')
    await expect(page.locator('.jc3-log .jc3-turn')).toHaveCount(TURNS.length)
    const sending = frames(page, m, 'level', 24)
    await expect(page.getByTestId('orb-level')).toContainText(/MIC -2\d dB/)
    await expect(page.getByTestId('orb-level')).toContainText('LIVE')
    await expect(page.locator('.jc3-hero')).toHaveAttribute('data-measured', 'true')
    await page.screenshot({ path: shot('1366-listening') })
    await sending
    // no frame for 400 ms: the level words come back by themselves
    await expect(page.getByTestId('orb-level')).toContainText('MIC no level yet', { timeout: 2000 })
    await expectNoOverlap(page)
    await expectNewestClear(page)

    // thinking: no level, the THINK lamp lit
    send(m, { kind: 'state', state: 'thinking' })
    await expect(page.getByTestId('orb-word')).toHaveText('Thinking')
    await expect(page.locator('.jc3-path-step[data-on]')).toHaveAttribute('data-stage', 'think')
    await page.waitForTimeout(500)
    await page.screenshot({ path: shot('1366-thinking') })

    // speaking with speaker frames
    send(m, { kind: 'state', state: 'speaking' })
    await expect(page.getByTestId('orb-word')).toHaveText('Speaking')
    const speaking = frames(page, m, 'out_level', 30)
    await expect(page.getByTestId('orb-level')).toContainText(/SPEAKER -2\d dB/)
    await page.waitForTimeout(400)
    await page.screenshot({ path: shot('1366-speaking') })
    await speaking
    await expectNoOverlap(page)
    await expectKeys44(page)
    await expectNewestClear(page)

    // scrolling up brings an older turn into the opaque part: the fade follows the log's viewport, not the lines
    await page.locator('.jc3-log-scroll').evaluate((el) => el.scrollTo(0, 0))
    await page.waitForTimeout(200)
    await page.screenshot({ path: shot('1366-scrolled-up') })
    const first = await page.evaluate(() => {
      const sc = document.querySelector('.jc3-log-scroll')!.getBoundingClientRect()
      const r = document.querySelector('.jc3-log .jc3-turn')!.getBoundingClientRect()
      return { top: r.top - sc.top, h: sc.height }
    })
    expect(first.top).toBeLessThan(first.h * 0.58)

    expect(errors).toEqual([])
  })

  test('1366 x 768: a core that stopped shows its own sentence under the orb', async ({ page, baseURL }) => {
    const m: Mock = { core: { ...OFF, last_error: 'exited with code 1: no input device', exit_code: 1, status_line: 'Offline: exited with code 1: no input device' }, turns: [], started: [], sockets: [] }
    await mockEngine(page, m)
    await open(page, baseURL, DESKTOP)
    await expect(page.getByTestId('orb-word')).toHaveText('Stopped')
    await expect(page.getByTestId('orb-line')).toContainText('exited with code 1: no input device')
    await page.screenshot({ path: shot('1366-stopped') })
  })

  test('390 x 844: orb on top, the act row, the conversation, the keys; nothing under the dock or the tab bar', async ({ page, baseURL }) => {
    const errors: string[] = []
    page.on('pageerror', (e) => errors.push(e.message))
    const m: Mock = { core: awake('speaking'), turns: TURNS, started: [], sockets: [] }
    await mockEngine(page, m)
    await open(page, baseURL, PHONE)
    await page.waitForTimeout(700)
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true)
    const orb = await boxOf(page, '.jc3-orb')
    expect(orb.width).toBeGreaterThanOrEqual(180)
    expect(orb.x).toBeGreaterThanOrEqual(0)
    expect(orb.x + orb.width).toBeLessThanOrEqual(PHONE.width)
    await expectNoOverlap(page)
    await expectKeys44(page)
    // the view's scroller ends above the dock and the tab bar: what scrolls under them is clipped, never drawn over them
    const zones = await boxOf(page, '.jc3 .s3-zones')
    for (const sel of ['.s3-dock', '.s3-tabbar']) {
      if (!(await page.locator(sel).count())) continue
      const b = await boxOf(page, sel)
      expect(overlap(zones, b), `the view overlaps ${sel}`).toBe(false)
    }
    const speaking = frames(page, m, 'out_level', 20)
    await page.waitForTimeout(300)
    await page.screenshot({ path: shot('390-speaking-top') })
    await speaking
    await page.locator('.jc3 .s3-zones').evaluate((el) => el.scrollTo(0, el.scrollHeight))
    await page.waitForTimeout(200)
    await page.screenshot({ path: shot('390-speaking-bottom') })
    expect(errors).toEqual([])
  })

  test('390 x 844 asleep, and reduced motion leaves no running animation in the view', async ({ page, baseURL }) => {
    await page.emulateMedia({ reducedMotion: 'reduce' })
    const m: Mock = { core: OFF, turns: [], started: [], sockets: [] }
    await mockEngine(page, m)
    await open(page, baseURL, PHONE)
    await page.waitForTimeout(700)
    await expect(page.locator('.jc3-hero')).toHaveAttribute('data-form', 'still')
    const n = await page.evaluate(() => (document as unknown as { getAnimations(o: object): Animation[] }).getAnimations({ subtree: true })
      .filter((a) => a.playState === 'running' && a.effect && ((a.effect as KeyframeEffect).target as Element | null)?.closest('.jc3')).length)
    expect(n).toBe(0)
    await page.screenshot({ path: shot('390-asleep-still') })
  })
})
